import re

_OPEN_TITLE = re.compile(r"<title(?:\s[^>]*)?>", re.IGNORECASE)
_CLOSE_TITLE = re.compile(r"</title\s*>", re.IGNORECASE)


def title_of(html: str) -> str:
    """Return the text of the first <title> element in html, or "".

    Tag names match case-insensitively, and the opening tag may carry
    attributes (e.g. ``<title id="t">``). The text runs from the end of the
    opening tag to the next ``</title>`` and may span several lines. Leading
    and trailing whitespace is stripped, and HTML entities are left as is.
    Returns "" if there is no ``<title>``, if it is never closed, or if it
    is empty. Only the given string is examined; nothing is fetched.
    """
    opening = _OPEN_TITLE.search(html)
    if opening is None:
        return ""
    closing = _CLOSE_TITLE.search(html, opening.end())
    if closing is None:
        return ""
    return html[opening.end() : closing.start()].strip()


def test_basic() -> None:
    html = "<html><head><title>Hello</title></head><body></body></html>"
    assert title_of(html) == "Hello"


def test_empty_input() -> None:
    assert title_of("") == ""


def test_no_title() -> None:
    assert title_of("<html><body><h1>Hi</h1></body></html>") == ""


def test_empty_title() -> None:
    assert title_of("<head><title></title></head>") == ""


def test_whitespace_only_title() -> None:
    assert title_of("<title>   \n </title>") == ""


def test_unclosed_title() -> None:
    assert title_of("<head><title>Oops</head><body></body>") == ""


def test_case_insensitive_tags() -> None:
    assert title_of("<HTML><TITLE>Shout</TITLE></HTML>") == "Shout"
    assert title_of("<Title>Mixed</tItLe>") == "Mixed"


def test_strips_surrounding_whitespace() -> None:
    assert title_of("<title>\n  My Page \n</title>") == "My Page"


def test_multiline_inner_text_preserved() -> None:
    assert title_of("<title>Line one\nLine two</title>") == "Line one\nLine two"


def test_first_title_wins() -> None:
    assert title_of("<title>First</title><title>Second</title>") == "First"


def test_title_with_attributes() -> None:
    assert title_of('<title id="t" lang="en">Attr</title>') == "Attr"


def test_entities_not_decoded() -> None:
    assert title_of("<title>Tom &amp; Jerry</title>") == "Tom &amp; Jerry"


def test_similar_tag_name_ignored() -> None:
    assert title_of("<titles>Nope</titles>") == ""
    assert title_of("<titles>Nope</titles><title>Yes</title>") == "Yes"

